options.css:
:root{}
.hm-root{--bg:#10141b;--bg2:#151a22;--border:rgba(255,255,255,.08);--text:#e4e7eb;
--dim:#8b93a1;--dim2:#666e7b;--accent:#c6ff4d;--accent-dim:rgba(198,255,77,.14);
--cpu:#6ee787;--mem:#d9c94a;--disk:#ffa94d;--net:#4dabf7;
--crit:#f2495c;--warn:#ff9830;--info:#5794f2;--ok:#6ee787;
font-family:inherit;color:var(--text);height:100%;box-sizing:border-box}
.hm-root *{box-sizing:border-box}
.hm-pill{display:inline-flex;align-items:center;gap:4px;padding:2px 9px;border-radius:20px;
background:rgba(255,255,255,.06);border:1px solid var(--border);font-size:10.5px;color:var(--dim);
white-space:nowrap;font-weight:600;letter-spacing:.02em}
.hm-badge{display:inline-flex;align-items:center;gap:5px;padding:2px 9px;border-radius:4px;
font-size:10.5px;font-weight:700;letter-spacing:.03em;text-transform:uppercase}
.hm-badge.ok{background:rgba(110,231,135,.15);color:var(--cpu)}
.hm-badge.crit{background:rgba(242,73,92,.18);color:var(--crit)}
.hm-badge.warn{background:rgba(255,152,48,.16);color:var(--warn)}
.hm-badge.info{background:rgba(87,148,242,.18);color:var(--info)}
.hm-empty{display:flex;align-items:center;justify-content:center;height:100%;opacity:.45;font-size:12px}
.hm-dotlive{width:7px;height:7px;border-radius:50%;background:var(--crit);display:inline-block;
box-shadow:0 0 0 0 rgba(242,73,92,.6);animation:hmpulse 1.6s infinite}
@keyframes hmpulse{0%{box-shadow:0 0 0 0 rgba(242,73,92,.55)}70%{box-shadow:0 0 0 6px rgba(242,73,92,0)}100%{box-shadow:0 0 0 0 rgba(242,73,92,0)}}
.hm-scroll{overflow:auto;height:100%}
.hm-scroll::-webkit-scrollbar{width:6px;height:6px}
.hm-scroll::-webkit-scrollbar-thumb{background:rgba(255,255,255,.12);border-radius:3px}

.hm-top{display:flex;align-items:center;justify-content:space-between;padding:7px 16px;border-bottom:1px solid var(--border)}
.hm-brand{display:flex;align-items:center;gap:9px;font-weight:700;font-size:12.5px;letter-spacing:.03em;color:#fff}
.hm-logo{display:inline-flex;gap:2px;flex-wrap:wrap;width:14px}
.hm-logo span{width:5px;height:5px;background:var(--accent);display:inline-block;border-radius:1px}
.hm-brand .sep{opacity:.3;font-weight:400;margin:0 1px}
.hm-brand .sub{opacity:.6;font-weight:700;font-size:11px;letter-spacing:.06em}
.hm-top-right{display:flex;align-items:center;gap:16px;font-size:11px;color:var(--dim)}
.hm-live{display:flex;align-items:center;gap:6px;color:var(--cpu);font-weight:700;letter-spacing:.05em;font-size:10.5px}
.hm-clock{font-variant-numeric:tabular-nums;color:#fff;font-weight:600;font-size:12px}
.hm-hostrow{display:flex;align-items:center;gap:22px;padding:11px 16px;height:calc(100% - 38px)}
.hm-hosticon{width:38px;height:38px;border-radius:8px;background:rgba(255,255,255,.05);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;font-size:17px;flex-shrink:0}
.hm-hostname{font-size:14.5px;font-weight:700;color:#fff;display:flex;align-items:center;gap:8px}
.hm-hostmeta{font-size:11px;color:var(--dim);margin-top:4px}
.hm-ministats{display:flex;flex:1;justify-content:flex-end;gap:28px;flex-wrap:wrap}
.hm-mini{text-align:right}
.hm-mini label{display:block;font-size:9px;letter-spacing:.06em;color:var(--dim2);text-transform:uppercase;font-weight:700;margin-bottom:3px}
.hm-mini .v{font-size:16px;font-weight:700;color:#fff;font-variant-numeric:tabular-nums;white-space:nowrap}

options.onRender:
function hgEl(id){return htmlNode.getElementById(id);}
function hgFmtBytes(b,d){if(b===null||b===undefined||isNaN(b))return '--';var u=['B','KB','MB','GB','TB','PB'];var i=0;var v=Math.abs(b);while(v>=1024&&i<u.length-1){v/=1024;i++;}return (b<0?'-':'')+v.toFixed(d===undefined?1:d)+' '+u[i];}
function hgFmtDuration(s){if(s===null||s===undefined||isNaN(s))return '--';s=Math.max(0,s);var d=Math.floor(s/86400);var h=Math.floor((s%86400)/3600);var m=Math.floor((s%3600)/60);if(d>0)return d+'d '+h+'h';if(h>0)return h+'h '+m+'m';if(m>0)return m+'m';return Math.floor(s)+'s';}
function hgFmtAgo(ms){return hgFmtDuration(ms/1000);}
function hgNum(v,d){if(v===null||v===undefined||isNaN(v))return '--';return v.toLocaleString('pt-BR',{minimumFractionDigits:d===undefined?0:d,maximumFractionDigits:d===undefined?0:d});}
function hgSeries(refId){return ((htmlGraphics.data&&htmlGraphics.data.series)||[]).filter(function(s){return s.refId===refId;});}
function hgFieldValues(f){if(!f||!f.values)return [];return f.values.toArray?f.values.toArray():f.values;}
function hgNumField(frame){return (frame.fields||[]).find(function(x){return x.type==='number';});}
function hgTimeField(frame){return (frame.fields||[]).find(function(x){return x.type==='time';});}
function hgStringField(frame){return (frame.fields||[]).find(function(x){return x.type==='string';});}
function hgLastValue(refId){var arr=hgSeries(refId);if(!arr.length)return null;var f=hgNumField(arr[0]);if(!f)return null;var v=hgFieldValues(f);return v.length?v[v.length-1]:null;}
function hgFirstValue(refId){var arr=hgSeries(refId);if(!arr.length)return null;var f=hgNumField(arr[0]);if(!f)return null;var v=hgFieldValues(f);return v.length?v[0]:null;}
function hgSeriesLabels(frame){var f=hgNumField(frame);return (f&&f.labels)||{};}
function hgSeriesName(frame){if(frame.name)return frame.name;var f=hgNumField(frame);if(f&&f.labels){var keys=Object.keys(f.labels).filter(function(k){return k!=='__name__';});if(keys.length)return keys.map(function(k){return f.labels[k];}).join(' ');}return frame.refId||'série';}
function hgAllInstant(refId){return hgSeries(refId).map(function(f){var vf=hgNumField(f);var vals=hgFieldValues(vf);return {v:vals.length?vals[vals.length-1]:null,labels:hgSeriesLabels(f),name:hgSeriesName(f)};}).filter(function(r){return r.v!==null&&r.v!==undefined;});}
function hgRangeVals(refId){var arr=hgSeries(refId);if(!arr.length)return {t:[],v:[]};var f=arr[0];var tf=hgTimeField(f),vf=hgNumField(f);return {t:hgFieldValues(tf),v:hgFieldValues(vf)};}
function hgRangeStats(refId){var r=hgRangeVals(refId);var vals=r.v.filter(function(x){return x!==null&&x!==undefined&&!isNaN(x);});if(!vals.length)return {min:null,max:null,first:null,last:null,avg:null};var sum=0;for(var i=0;i<vals.length;i++)sum+=vals[i];return {min:Math.min.apply(null,vals),max:Math.max.apply(null,vals),first:vals[0],last:vals[vals.length-1],avg:sum/vals.length};}
var HG_PAL=['#6ee787','#4dabf7','#ffa94d','#f2495c','#b877d9','#d9c94a','#8ab8ff','#fade2a','#a352cc','#37872d'];
function hgPalColor(i){return HG_PAL[i%HG_PAL.length];}
function hgPct(v,d){if(v===null||v===undefined||isNaN(v))return '--';return v.toFixed(d===undefined?1:d)+'%';}
function hgEsc(s){return String(s===undefined||s===null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;');}
function hgDeltaBadge(delta,unit,mode,decimals){
  decimals=decimals===undefined?1:decimals;
  if(delta===null||delta===undefined||isNaN(delta))return '<span class="hm-delta hm-delta-flat">sem base de comparação</span>';
  var up=delta>=0;var arrow=up?'↑':'↓';
  var cls='hm-delta-flat';
  if(Math.abs(delta)>=0.05){
    if(mode==='bad-up')cls=up?'hm-delta-up':'hm-delta-down';
    else if(mode==='bad-down')cls=up?'hm-delta-down':'hm-delta-up';
  }
  return '<span class="hm-delta '+cls+'">'+arrow+' '+Math.abs(delta).toFixed(decimals)+unit+'</span>';
}
function hgApplyCard(root,valueTxt,unitTxt,deltaHtml,metaHtml,subTxt,sparkVals,color,threshold){
  if(!root)return;
  root.querySelector('[data-value]').textContent=valueTxt;
  var u=root.querySelector('.hm-card-unit');if(u&&unitTxt!==undefined)u.textContent=unitTxt;
  var dEl=root.querySelector('[data-delta]');if(dEl)dEl.innerHTML=deltaHtml;
  var mEl=root.querySelector('[data-meta]');if(mEl)mEl.innerHTML=metaHtml;
  if(subTxt!==undefined){var s=root.querySelector('[data-sub]');if(s)s.textContent=subTxt;}
  hgSparkline(root.querySelector('[data-spark]'),sparkVals,color,{threshold:threshold});
}
function hgSparkline(root,vals,color,opts){
  opts=opts||{};
  if(!root)return;
  var rect=root.getBoundingClientRect();
  var W=Math.max(rect.width,20),H=Math.max(rect.height,16);
  var clean=vals.filter(function(v){return v!==null&&v!==undefined&&!isNaN(v);});
  if(clean.length<2){root.innerHTML='';return;}
  var min=opts.min!==undefined?opts.min:Math.min.apply(null,vals.map(function(v){return isNaN(v)?Infinity:v;}));
  var max=opts.max!==undefined?opts.max:Math.max.apply(null,vals.map(function(v){return isNaN(v)?-Infinity:v;}));
  if(max===min){max=min+1;}
  var n=vals.length;
  var pts=[];
  for(var i=0;i<n;i++){
    if(vals[i]===null||vals[i]===undefined||isNaN(vals[i]))continue;
    var x=(i/(n-1))*W;
    var y=H-((vals[i]-min)/(max-min))*H;
    pts.push([x,y]);
  }
  var svgNS='http://www.w3.org/2000/svg';
  var svg=document.createElementNS(svgNS,'svg');
  svg.setAttribute('width','100%');svg.setAttribute('height','100%');svg.setAttribute('viewBox','0 0 '+W+' '+H);svg.style.display='block';svg.style.overflow='visible';
  if(opts.threshold!==undefined&&opts.threshold>=min&&opts.threshold<=max){
    var ty=H-((opts.threshold-min)/(max-min))*H;
    var tl=document.createElementNS(svgNS,'line');
    tl.setAttribute('x1',0);tl.setAttribute('x2',W);tl.setAttribute('y1',ty);tl.setAttribute('y2',ty);
    tl.setAttribute('stroke','rgba(255,255,255,.22)');tl.setAttribute('stroke-width','1');tl.setAttribute('stroke-dasharray','3,3');
    svg.appendChild(tl);
  }
  var lineD='M'+pts.map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' L');
  var areaD=lineD+' L'+pts[pts.length-1][0].toFixed(1)+','+H+' L'+pts[0][0].toFixed(1)+','+H+' Z';
  var area=document.createElementNS(svgNS,'path');
  area.setAttribute('d',areaD);area.setAttribute('fill',color);area.setAttribute('fill-opacity','0.16');area.setAttribute('stroke','none');
  svg.appendChild(area);
  var line=document.createElementNS(svgNS,'path');
  line.setAttribute('d',lineD);line.setAttribute('fill','none');line.setAttribute('stroke',color);line.setAttribute('stroke-width','1.6');
  svg.appendChild(line);
  var last=pts[pts.length-1];
  var dot=document.createElementNS(svgNS,'circle');
  dot.setAttribute('cx',last[0]);dot.setAttribute('cy',last[1]);dot.setAttribute('r','2.2');dot.setAttribute('fill',color);
  svg.appendChild(dot);
  root.innerHTML='';root.appendChild(svg);
}
function hgStackedChart(root,seriesDefs,opts){
  opts=opts||{};
  if(!root)return;
  var rect=root.getBoundingClientRect();
  var W=Math.max(rect.width,80),H=Math.max(rect.height,60);
  var padL=opts.leftPad||34,padR=8,padT=8,padB=16;
  var plotW=Math.max(W-padL-padR,10),plotH=Math.max(H-padT-padB,10);
  var n=0;
  seriesDefs.forEach(function(s){if(s.v.length>n)n=s.v.length;});
  if(!n){root.innerHTML='<div class="hm-empty">sem dados</div>';return;}
  var tMin=seriesDefs[0].t[0],tMax=seriesDefs[0].t[seriesDefs[0].t.length-1];
  if(tMax===tMin)tMax=tMin+1;
  var maxTotal=0;
  for(var i=0;i<n;i++){var tot=0;seriesDefs.forEach(function(s){tot+=(s.v[i]||0);});if(tot>maxTotal)maxTotal=tot;}
  var yMax=opts.max||Math.max(maxTotal*1.15,10);
  function xOf(t){return padL+((t-tMin)/(tMax-tMin))*plotW;}
  function yOf(v){return padT+plotH-(v/yMax)*plotH;}
  var svgNS='http://www.w3.org/2000/svg';
  var svg=document.createElementNS(svgNS,'svg');
  svg.setAttribute('width','100%');svg.setAttribute('height','100%');svg.setAttribute('viewBox','0 0 '+W+' '+H);svg.style.display='block';svg.style.overflow='visible';
  function gline(y,txt){
    var l=document.createElementNS(svgNS,'line');l.setAttribute('x1',padL);l.setAttribute('x2',padL+plotW);l.setAttribute('y1',y);l.setAttribute('y2',y);l.setAttribute('stroke','rgba(255,255,255,.07)');svg.appendChild(l);
    var t=document.createElementNS(svgNS,'text');t.setAttribute('x',padL-6);t.setAttribute('y',y+3);t.setAttribute('fill','#7a8290');t.setAttribute('font-size','9');t.setAttribute('text-anchor','end');t.textContent=txt;svg.appendChild(t);
  }
  gline(padT,yMax.toFixed(0)+'%');gline(padT+plotH/2,(yMax/2).toFixed(0)+'%');gline(padT+plotH,'0%');
  if(opts.threshold!==undefined&&opts.threshold<=yMax){
    var ty=yOf(opts.threshold);
    var tl=document.createElementNS(svgNS,'line');tl.setAttribute('x1',padL);tl.setAttribute('x2',padL+plotW);tl.setAttribute('y1',ty);tl.setAttribute('y2',ty);
    tl.setAttribute('stroke','rgba(255,152,48,.55)');tl.setAttribute('stroke-width','1');tl.setAttribute('stroke-dasharray','4,3');svg.appendChild(tl);
    var lt=document.createElementNS(svgNS,'text');lt.setAttribute('x',padL+plotW-2);lt.setAttribute('y',ty-3);lt.setAttribute('fill','#ff9830');lt.setAttribute('font-size','9');lt.setAttribute('text-anchor','end');lt.textContent='ATENÇÃO '+opts.threshold+'%';svg.appendChild(lt);
  }
  var stackBase=new Array(n).fill(0);
  seriesDefs.forEach(function(s){
    var topPts=[],botPts=[];
    for(var i=0;i<n;i++){
      var v=s.v[i]||0;
      var base=stackBase[i];
      var top=base+v;
      topPts.push([xOf(s.t[i]),yOf(top)]);
      botPts.push([xOf(s.t[i]),yOf(base)]);
      stackBase[i]=top;
    }
    var d='M'+topPts.map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' L')+' L'+botPts.slice().reverse().map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' L')+' Z';
    var path=document.createElementNS(svgNS,'path');
    path.setAttribute('d',d);path.setAttribute('fill',s.color);path.setAttribute('fill-opacity','0.75');path.setAttribute('stroke',s.color);path.setAttribute('stroke-width','0.5');
    svg.appendChild(path);
  });
  var totalPts=[];
  for(var j=0;j<n;j++)totalPts.push([xOf(seriesDefs[0].t[j]),yOf(stackBase[j])]);
  var totalPath=document.createElementNS(svgNS,'path');
  totalPath.setAttribute('d','M'+totalPts.map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' L'));
  totalPath.setAttribute('fill','none');totalPath.setAttribute('stroke','rgba(255,255,255,.55)');totalPath.setAttribute('stroke-width','1.2');
  svg.appendChild(totalPath);
  var vline=document.createElementNS(svgNS,'line');vline.setAttribute('y1',padT);vline.setAttribute('y2',padT+plotH);vline.setAttribute('stroke','rgba(255,255,255,.3)');vline.style.display='none';svg.appendChild(vline);
  var tooltip=document.createElement('div');tooltip.className='hg-chart-tooltip';tooltip.style.display='none';tooltip.style.position='absolute';
  root.style.position='relative';
  svg.addEventListener('mousemove',function(ev){
    var r=svg.getBoundingClientRect();var mx=(ev.clientX-r.left)*(W/r.width);
    if(mx<padL||mx>padL+plotW){tooltip.style.display='none';vline.style.display='none';return;}
    var t=tMin+((mx-padL)/plotW)*(tMax-tMin);
    var bestI=0,bestD=Infinity;
    for(var k=0;k<seriesDefs[0].t.length;k++){var dd=Math.abs(seriesDefs[0].t[k]-t);if(dd<bestD){bestD=dd;bestI=k;}}
    vline.setAttribute('x1',mx);vline.setAttribute('x2',mx);vline.style.display='block';
    var rows=seriesDefs.map(function(s){return '<div class="hg-tt-row"><span class="hg-tt-dot" style="background:'+s.color+'"></span><span class="hg-tt-name">'+s.name+'</span><span class="hg-tt-val">'+(s.v[bestI]||0).toFixed(1)+'%</span></div>';}).join('');
    tooltip.innerHTML='<div class="hg-tt-time">'+new Date(seriesDefs[0].t[bestI]).toLocaleTimeString()+'</div>'+rows+'<div class="hg-tt-row"><b>total '+stackBase[bestI].toFixed(1)+'%</b></div>';
    tooltip.style.display='block';
    var left=ev.clientX-r.left+10;if(left+170>r.width)left=ev.clientX-r.left-180;
    tooltip.style.left=left+'px';tooltip.style.top=(ev.clientY-r.top-10)+'px';
  });
  svg.addEventListener('mouseleave',function(){tooltip.style.display='none';vline.style.display='none';});
  root.innerHTML='';root.appendChild(svg);root.appendChild(tooltip);
}
function hgRenderLines(root,seriesDefs,opts){
  opts=opts||{};
  if(!root)return;
  var fmt=opts.fmt||function(v){return v===null||v===undefined||isNaN(v)?'--':v.toFixed(opts.decimals!==undefined?opts.decimals:1);};
  var rect=root.getBoundingClientRect();
  var W=Math.max(rect.width,80),H=Math.max(rect.height,60);
  var padL=opts.leftPad||40,padR=8,padT=8,padB=16;
  var plotW=Math.max(W-padL-padR,10),plotH=Math.max(H-padT-padB,10);
  var valid=seriesDefs.filter(function(s){return s.t&&s.t.length>0;});
  if(!valid.length){root.innerHTML='<div class="hm-empty">sem dados</div>';return;}
  var tMin=Math.min.apply(null,valid.map(function(s){return s.t[0];}));
  var tMax=Math.max.apply(null,valid.map(function(s){return s.t[s.t.length-1];}));
  if(tMax===tMin)tMax=tMin+1;
  var yMin=opts.min!==undefined?opts.min:Infinity;
  var yMax=opts.max!==undefined?opts.max:-Infinity;
  var autoMin=opts.min===undefined,autoMax=opts.max===undefined;
  valid.forEach(function(s){s.v.forEach(function(v){if(v===null||v===undefined||isNaN(v))return;if(autoMax&&v>yMax)yMax=v;if(autoMin&&v<yMin)yMin=v;});});
  if(!isFinite(yMin))yMin=0;
  if(!isFinite(yMax))yMax=1;
  if(autoMin&&yMin>0)yMin=0;
  if(yMax===yMin)yMax=yMin+1;
  if(autoMax)yMax=yMax*1.1;
  function xOf(t){return padL+((t-tMin)/(tMax-tMin))*plotW;}
  function yOf(v){return padT+plotH-((v-yMin)/(yMax-yMin))*plotH;}
  var svgNS='http://www.w3.org/2000/svg';
  var svg=document.createElementNS(svgNS,'svg');
  svg.setAttribute('width','100%');svg.setAttribute('height','100%');svg.setAttribute('viewBox','0 0 '+W+' '+H);svg.style.display='block';svg.style.overflow='visible';
  [0,0.5,1].forEach(function(frac){
    var v=yMin+(yMax-yMin)*(1-frac);
    var y=padT+plotH*frac;
    var l=document.createElementNS(svgNS,'line');l.setAttribute('x1',padL);l.setAttribute('x2',padL+plotW);l.setAttribute('y1',y);l.setAttribute('y2',y);l.setAttribute('stroke','rgba(255,255,255,.07)');svg.appendChild(l);
    var t=document.createElementNS(svgNS,'text');t.setAttribute('x',padL-6);t.setAttribute('y',y+3);t.setAttribute('fill','#7a8290');t.setAttribute('font-size','9');t.setAttribute('text-anchor','end');t.textContent=fmt(v);svg.appendChild(t);
  });
  if(opts.threshold!==undefined&&opts.threshold>=yMin&&opts.threshold<=yMax){
    var ty=yOf(opts.threshold);
    var tl=document.createElementNS(svgNS,'line');tl.setAttribute('x1',padL);tl.setAttribute('x2',padL+plotW);tl.setAttribute('y1',ty);tl.setAttribute('y2',ty);
    tl.setAttribute('stroke','rgba(255,152,48,.5)');tl.setAttribute('stroke-width','1');tl.setAttribute('stroke-dasharray','4,3');svg.appendChild(tl);
  }
  valid.forEach(function(s){
    var pts=[];
    for(var i=0;i<s.t.length;i++){
      if(s.v[i]===null||s.v[i]===undefined||isNaN(s.v[i]))continue;
      pts.push([xOf(s.t[i]),yOf(s.v[i])]);
    }
    if(!pts.length)return;
    if(opts.area!==false){
      var baseline=yOf(Math.max(yMin,0));
      var areaD='M'+pts[0][0].toFixed(1)+','+baseline.toFixed(1)+' L'+pts.map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' L')+' L'+pts[pts.length-1][0].toFixed(1)+','+baseline.toFixed(1)+' Z';
      var area=document.createElementNS(svgNS,'path');
      area.setAttribute('d',areaD);area.setAttribute('fill',s.color);area.setAttribute('fill-opacity',(opts.fillOpacity!==undefined?opts.fillOpacity:10)/100);area.setAttribute('stroke','none');
      svg.appendChild(area);
    }
    var line=document.createElementNS(svgNS,'path');
    line.setAttribute('d','M'+pts.map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}).join(' L'));
    line.setAttribute('fill','none');line.setAttribute('stroke',s.color);line.setAttribute('stroke-width','1.6');
    svg.appendChild(line);
  });
  var vline=document.createElementNS(svgNS,'line');vline.setAttribute('y1',padT);vline.setAttribute('y2',padT+plotH);vline.setAttribute('stroke','rgba(255,255,255,.3)');vline.style.display='none';svg.appendChild(vline);
  var tooltip=document.createElement('div');tooltip.className='hg-chart-tooltip';tooltip.style.display='none';tooltip.style.position='absolute';
  root.style.position='relative';
  svg.addEventListener('mousemove',function(ev){
    var r=svg.getBoundingClientRect();var mx=(ev.clientX-r.left)*(W/r.width);
    if(mx<padL||mx>padL+plotW){tooltip.style.display='none';vline.style.display='none';return;}
    var t=tMin+((mx-padL)/plotW)*(tMax-tMin);
    vline.setAttribute('x1',mx);vline.setAttribute('x2',mx);vline.style.display='block';
    var rows=valid.map(function(s){
      var bestI=0,bestD=Infinity;
      for(var i=0;i<s.t.length;i++){var dd=Math.abs(s.t[i]-t);if(dd<bestD){bestD=dd;bestI=i;}}
      return {name:s.name,v:s.v[bestI],color:s.color};
    }).sort(function(a,b){return (b.v||0)-(a.v||0);}).slice(0,8);
    var timeLabel=new Date(t).toLocaleTimeString('pt-BR');
    tooltip.innerHTML='<div class="hg-tt-time">'+timeLabel+'</div>'+rows.map(function(r){return '<div class="hg-tt-row"><span class="hg-tt-dot" style="background:'+r.color+'"></span><span class="hg-tt-name">'+hgEsc(r.name)+'</span><span class="hg-tt-val">'+fmt(r.v)+'</span></div>';}).join('');
    tooltip.style.display='block';
    var left=ev.clientX-r.left+10;if(left+190>r.width)left=ev.clientX-r.left-200;
    tooltip.style.left=left+'px';tooltip.style.top=(ev.clientY-r.top-10)+'px';
  });
  svg.addEventListener('mouseleave',function(){tooltip.style.display='none';vline.style.display='none';});
  root.innerHTML='';root.appendChild(svg);root.appendChild(tooltip);
  if(opts.legendEl){
    opts.legendEl.innerHTML=valid.map(function(s){
      var last=null;
      for(var i=s.v.length-1;i>=0;i--){if(s.v[i]!==null&&s.v[i]!==undefined&&!isNaN(s.v[i])){last=s.v[i];break;}}
      return '<span><span class="hm-legend-dot" style="background:'+s.color+'"></span>'+hgEsc(s.name)+' <b>'+fmt(last)+'</b></span>';
    }).join('');
  }
}
function hgRenderLogs(root,refId,limit){
  if(!root)return;
  var frames=hgSeries(refId);
  if(!frames.length){root.innerHTML='<div class="hm-empty">sem dados</div>';return;}
  var rows=[];
  frames.forEach(function(f){
    var fields=f.fields||[];
    var tField=hgTimeField(f);
    var lineField=hgStringField(f);
    if(!tField||!lineField)return;
    var tVals=hgFieldValues(tField),lVals=hgFieldValues(lineField);
    var labelsField=fields.find(function(x){return x.name==='labels';});
    var labelVals=labelsField?hgFieldValues(labelsField):null;
    for(var i=0;i<tVals.length;i++){
      var labels=labelVals?labelVals[i]:null;
      var level=labels&&labels.detected_level?labels.detected_level:null;
      var line=lVals[i]||'';
      if(!level){
        var low=String(line).toLowerCase();
        if(low.indexOf('error')>=0||low.indexOf('erro')>=0)level='error';
        else if(low.indexOf('warn')>=0)level='warn';
      }
      rows.push({t:tVals[i],line:line,level:level,container:labels&&(labels.container||labels.compose_service)});
    }
  });
  rows.sort(function(a,b){return b.t-a.t;});
  limit=limit||500;
  var shown=rows.slice(0,limit);
  var levelColor={error:'#f2495c',critical:'#c4162a',fatal:'#c4162a',warn:'#ff9830',info:'#6ee787',debug:'#4dabf7',trace:'#8b93a1'};
  var html=shown.map(function(r){
    var lc=r.level&&levelColor[r.level]?levelColor[r.level]:'#8b93a1';
    var tag=r.level?'<span class="hg-log-level" style="background:'+lc+'22;color:'+lc+'">'+hgEsc(r.level)+'</span>':'';
    var ctag=r.container?'<span class="hg-log-container">'+hgEsc(r.container)+'</span>':'';
    return '<div class="hg-log-row"><span class="hg-log-time">'+new Date(r.t).toLocaleString('pt-BR')+'</span>'+tag+ctag+'<span class="hg-log-msg">'+hgEsc(r.line)+'</span></div>';
  }).join('');
  if(rows.length>limit)html+='<div class="hm-empty">mostrando '+limit+' de '+rows.length+' linhas</div>';
  root.innerHTML=html||'<div class="hm-empty">sem dados</div>';
}
function hgMultiSeriesFromRefId(refId,limit){
  var frames=hgSeries(refId);
  var out=frames.map(function(f,idx){
    return {name:hgSeriesName(f),t:hgFieldValues(hgTimeField(f)),v:hgFieldValues(hgNumField(f)),color:hgPalColor(idx)};
  });
  out.sort(function(a,b){
    var la=a.v.length?a.v[a.v.length-1]||0:0, lb=b.v.length?b.v[b.v.length-1]||0:0;
    return lb-la;
  });
  if(limit)out=out.slice(0,limit);
  out.forEach(function(s,idx){s.color=hgPalColor(idx);});
  return out;
}

try{
  var root=hgEl('hg-root-1');
